inner="\nfrom pathlib import Path\nimport json,numpy as np,torch\nfrom torch.nn import functional as F\nfrom experiments.pamf_phase1_flow import experiment as core,physical_rich_router_experiment as g,feature_conditioned_experiment as fs\nroot=Path('/home/szu2070436088/2510044040/CV-SincNet');torch.set_num_threads(2);models=g.load_models(root,'cpu');teacher,contract,dura,*_=models;cache,clean,roles=core.data(root,contract)\nfrom leo_practical.channel import Config,receiver_for_session,stable_seed,normalize_input\nfrom leo_practical.residual import ResidualChannel\nids=np.load(cache/'train/physical_ids.npy',allow_pickle=False);rx=np.load(cache/'train/rx.npy',allow_pickle=False);day=np.load(cache/'train/day.npy',allow_pickle=False)\nq_rng=np.random.default_rng(2026110251);h_rng=np.random.default_rng(2026110351);guard_rng=np.random.default_rng(2026110361);utility_rng=np.random.default_rng(2026110371);cycle_rng=np.random.default_rng(2026110411);snr_rng=np.random.default_rng(2026110451);fresh_rng=np.random.default_rng(2026110461);groups=[]\nfor role,q_count,h_count,guard_count,take,snr_count in (('L_s',2048,512,2048,1024,2048),('U_s',6144,1536,6144,3072,6144)):\n all_ids=np.flatnonzero(roles==role);q=q_rng.choice(all_ids,size=q_count,replace=False);h=h_rng.choice(all_ids,size=h_count,replace=False);without_h=np.setdiff1d(all_ids,np.sort(h),assume_unique=True);guard=guard_rng.choice(without_h,size=guard_count,replace=False);excluded=np.unique(np.concatenate((q,h,guard)));available=np.setdiff1d(all_ids,excluded,assume_unique=True);utility=utility_rng.choice(available,size=take,replace=False);available=np.setdiff1d(available,np.sort(utility),assume_unique=True);cycle=cycle_rng.choice(available,size=take,replace=False);snr=snr_rng.choice(all_ids,size=snr_count,replace=False);available=np.setdiff1d(all_ids,np.unique(np.concatenate((cycle,snr))),assume_unique=True);assert len(available)>=snr_count;fresh=np.sort(fresh_rng.choice(available,size=snr_count,replace=False));assert not np.intersect1d(fresh,cycle).size and not np.intersect1d(fresh,snr).size;groups.append(fresh)\nfixed=np.concatenate(groups);assert len(fixed)==len(np.unique(fixed))==8192;source_rx=rx[fixed];source_day=day[fixed];split=np.full(len(fixed),-1,dtype=np.int64);split[np.isin(source_rx,[1,3,4])&np.isin(source_day,[1,2])]=0;split[np.isin(source_rx,[4,6])&(source_day==3)]=1;split[(source_rx==8)&(source_day==3)]=2;keep=split>0;fixed=fixed[keep];source_rx=source_rx[keep];source_day=source_day[keep];split=split[keep];n=len(fixed);assert n>300\nviews=('clean','practical_low_suburban','practical_mid_urban','practical_low_urban');alphas=(-.3,-.1,-.03,.03,.1,.3);period=20;data={};clean_iq=np.asarray(clean[fixed],dtype=np.float32);clean_complex=clean_iq[:,0].astype(np.float64)+1j*clean_iq[:,1];cycles=np.arange(256)//period;residues=np.arange(256)%period\ndef project(z):\n phi=np.angle(np.sum(np.conj(z[:,:-period])*z[:,period:],axis=1));demod=z*np.exp(-1j*phi[:,None]*cycles);mean=np.stack([np.mean(demod[:,r::period],axis=1) for r in range(period)],1);out=mean[:,residues]*np.exp(1j*phi[:,None]*cycles);return out,phi\ndef align_to_anchor(wave,anchor):\n pad=np.pad(wave,((0,0),(16,16)),mode='reflect');target=anchor[:,16:-16];best=np.full(len(wave),np.inf);chosen=np.zeros_like(wave)\n for shift in range(-16,17):\n  full=pad[:,16+shift:16+shift+256];part=full[:,16:-16];gain=np.sum(np.conj(part)*target,axis=1)/np.maximum(np.sum(abs(part)**2,axis=1),1e-20);mse=np.mean(abs(gain[:,None]*part-target)**2,axis=1);use=mse<best;best[use]=mse[use];chosen[use]=gain[use,None]*full[use]\n return chosen\ndef remove_cycle(z):\n mean=np.stack([np.mean(z[:,r::period],axis=1) for r in range(period)],1);return z-mean[:,residues]\ndef wide_mse(wave,truth):\n pad=np.pad(wave,((0,0),(64,64)),mode='reflect');target=truth[:,64:-64];best=np.full(len(wave),np.inf)\n for shift in range(-64,65):\n  part=pad[:,64+shift:64+shift+256][:,64:-64];gain=np.sum(np.conj(part)*target,axis=1)/np.maximum(np.sum(abs(part)**2,axis=1),1e-20);mse=np.mean(abs(gain[:,None]*part-target)**2,axis=1);best=np.minimum(best,mse)\n return best\nfor view in views:\n snrs=[]\n if view=='clean':received=clean_iq;snrs=[0.]*n\n else:\n  cfg=Config(fs_hz=25e6,fc_hz=2462e6,scenario=view,processing_route='residual',mode='post_sync',equalization_enabled=False,reference_snr_db=30.,boundary='reflect');received=[]\n  for j in fixed:\n   pid=str(ids[j]);session='rx%d:day%d:eq1'%(int(rx[j]),int(day[j]));hw=receiver_for_session(cfg,2026110463,session);v=np.asarray(clean[j],dtype=np.float64);signal,_=normalize_input(v[0]+1j*v[1]);result,meta=ResidualChannel(cfg,stable_seed(2026110462,'source-gated-low-snr-2026110462',view,pid),hw).process(signal)\n   assert np.isfinite(result).all() and not meta['channel_equalization_applied'];received.append(np.stack((result.real,result.imag)).astype(np.float32));snrs.append(0.)\n  received=np.stack(received)\n anchors=[];rawp=[];basep=[]\n with torch.no_grad():\n  for start in range(0,n,32):\n   x=core.tensor(received[start:start+32],'cpu');a=dura(x);anchors.append(a.cpu());rawp.append(F.softmax(teacher.classify_features(teacher.features(x)),1).cpu());basep.append(F.softmax(teacher.classify_features(teacher.features(a)),1).cpu())\n anchor=np.from_dlpack(torch.cat(anchors).contiguous());rawp=np.from_dlpack(torch.cat(rawp).contiguous());basep=np.from_dlpack(torch.cat(basep).contiguous());z=anchor[:,0].astype(np.float64)+1j*anchor[:,1];cycle,phi=project(z);ratio=np.sqrt(np.sum((received-anchor)**2,axis=(1,2))/np.maximum(np.sum(received**2,axis=(1,2)),1e-12));gate=ratio>.2;candidates=[];probs=[]\n \n received_complex=received[:,0].astype(np.float64)+1j*received[:,1];raw_aligned=align_to_anchor(received_complex,z);clean_aligned=z.copy();rotation=np.exp(-1j*phi[:,None]*cycles);rms=np.sqrt(np.mean(abs(z)**2,axis=1)).clip(min=1e-8);canonical=z*rotation/rms[:,None];q_anchor=remove_cycle(canonical);q_raw=remove_cycle(raw_aligned*rotation/rms[:,None]);q_target=remove_cycle((clean_aligned-z)*rotation/rms[:,None]);features=np.stack((canonical.real,canonical.imag,q_anchor.real,q_anchor.imag,q_raw.real,q_raw.imag),1).astype(np.float32);features=np.pad(features,((0,0),(0,0),(0,4))).reshape(n,6,13,20);target_iq=np.stack((q_target.real,q_target.imag),1).astype(np.float32)\n clean_wave=np.stack((clean_aligned.real,clean_aligned.imag),1).astype(np.float32);target_features=[];target_probabilities=[]\n with torch.no_grad():\n  for start in range(0,n,64):\n   f=teacher.features(core.tensor(clean_wave[start:start+64],'cpu'));target_features.append(F.normalize(f,dim=1).cpu());target_probabilities.append(F.softmax(teacher.classify_features(f),1).cpu())\n rotation_inv=1/rotation;rotation_iq=np.stack((rotation_inv.real,rotation_inv.imag),1).astype(np.float32);anchor_iq=np.stack((z.real,z.imag),1).astype(np.float32)\n raw_energy=np.mean(abs(received_complex[:,64:-64])**2,axis=1).clip(min=1e-20);fraction=np.clip(wide_mse(z,received_complex)/raw_energy,1e-8,1.);blind_snr=10*np.log10(np.maximum(1-fraction,1e-8)/fraction);data[view]=dict(blind_snr=blind_snr,input=core.tensor(features,'cpu'),target=core.tensor(target_iq,'cpu'),anchor=z,anchor_t=core.tensor(anchor_iq,'cpu'),rotation_t=core.tensor(rotation_iq,'cpu'),rms_t=core.tensor(rms.astype(np.float32),'cpu'),target_feature=torch.cat(target_features).contiguous(),target_prob=torch.cat(target_probabilities).contiguous(),snr=core.tensor(np.asarray(snrs,dtype=np.float32),'cpu'),basep=basep,rawp=rawp,rotation=rotation,rms=rms,gate=gate);print('CYCLE_FEATURE_SOURCE_INPUTS_FIXED',view,flush=True)\nclass CycleNet(torch.nn.Module):\n def __init__(self):\n  super().__init__();self.net=torch.nn.Sequential(torch.nn.Conv2d(6,24,3,padding=1),torch.nn.GELU(),torch.nn.Conv2d(24,24,3,padding=2,dilation=2),torch.nn.GELU(),torch.nn.Conv2d(24,24,3,padding=4,dilation=4),torch.nn.GELU(),torch.nn.Conv2d(24,2,3,padding=1));torch.nn.init.zeros_(self.net[-1].weight);torch.nn.init.zeros_(self.net[-1].bias)\n def forward(self,x):\n  out=self.net(x).reshape(-1,2,260)[:,:,:256];mean=torch.stack([out[:,:,r::20].mean(2) for r in range(20)],2);return out-mean[:,:,torch.arange(256,device=out.device)%20]\n\nimport sys\npayload=json.load(sys.stdin);assert payload['alpha']==.25 and payload['gate_db']==10.;model=CycleNet();model.load_state_dict({k:torch.tensor(v,dtype=torch.float32) for k,v in payload['model_state'].items()});model.eval();predictions={};waves={}\nwith torch.no_grad():\n for view in views:\n  v=data[view];parts=[]\n  for start in range(0,n,128):parts.append(model(v['input'][start:start+128]).cpu())\n  d=np.from_dlpack(torch.cat(parts).contiguous());delta=(d[:,0].astype(np.float64)+1j*d[:,1])*v['rms'][:,None]/v['rotation'];ungated=v['anchor']+payload['alpha']*v['gate'][:,None]*delta;gate=v['gate']&(v['blind_snr']<payload['gate_db']);gated=v['anchor']+payload['alpha']*gate[:,None]*delta;waves[view]=dict(ungated=ungated,gated=gated);predictions[view]={}\n  for method,wave in waves[view].items():\n   wiq=np.stack((wave.real,wave.imag),1).astype(np.float32);out=[]\n   for start in range(0,n,64):\n    x=core.tensor(wiq[start:start+64],'cpu');out.append(F.softmax(teacher.classify_features(teacher.features(x)),1).cpu())\n   predictions[view][method]=np.from_dlpack(torch.cat(out).contiguous()).argmax(1)\nprint('FRESH_GATED_LOW_SNR_WAVEFORMS_FIXED_BEFORE_SOURCE_TX_LABELS',flush=True)\nlabels=fs.source_labels(root,cache,clean,roles,contract);labeled=roles[fixed]=='L_s';assert np.all(labels[fixed[~labeled]]==-1);ref=data['clean']['rawp'];teacher_target=ref.argmax(1);valid=labeled|(ref.max(1)>=.95);target=np.where(labeled,labels[fixed],teacher_target)\ndef aligned_mse(wave,truth):\n pad=np.pad(wave,((0,0),(16,16)),mode='reflect');truth=truth[:,16:-16];best=np.full(len(wave),np.inf)\n for shift in range(-16,17):\n  part=pad[:,16+shift:16+shift+256][:,16:-16];gain=np.sum(np.conj(part)*truth,axis=1)/np.maximum(np.sum(abs(part)**2,axis=1),1e-20);mse=np.mean(abs(gain[:,None]*part-truth)**2,axis=1);best=np.minimum(best,mse)\n return best\ndef evaluate(part,group=None):\n mask=split==part\n if group is not None:mask &= source_rx==group\n vm=mask&valid;lm=vm&labeled;results={}\n for view in views:\n  v=data[view];base=v['basep'].argmax(1);raw_correct=base==target;row=dict(count=int(mask.sum()),valid_count=int(vm.sum()),L_s_count=int(lm.sum()),U_confident_count=int((vm&~labeled).sum()),baseline=int((vm&raw_correct).sum()),L_s_baseline=int((lm&raw_correct).sum()),gate_enabled=int((mask&v['gate']&(v['blind_snr']<payload['gate_db'])).sum()))\n  for method in ('ungated','gated'):\n   out=predictions[view][method];ok=out==target;row[method]=dict(correct=int((vm&ok).sum()),repairs=int((vm&~raw_correct&ok).sum()),damages=int((vm&raw_correct&~ok).sum()),L_s_correct=int((lm&ok).sum()))\n  snr=np.from_dlpack(v['snr'].contiguous());truth=snr<10.;selected=v['blind_snr']<payload['gate_db'];row['blind_snr_confusion']=dict(true_low=int((mask&truth).sum()),true_positive=int((mask&truth&selected).sum()),false_positive=int((mask&~truth&selected).sum()),false_negative=int((mask&truth&~selected).sum()),true_negative=int((mask&~truth&~selected).sum()));results[view]=row\n return results\nquality={}\nfor view in views:\n v=data[view];m=split==2;truth=clean_complex[m];base=aligned_mse(v['anchor'][m],truth);q=dict(count=int(m.sum()),baseline=float(base.mean()))\n for method in ('ungated','gated'):\n  err=aligned_mse(waves[view][method][m],truth);q[method]=dict(aligned_mse=float(err.mean()),improved=int((err<base).sum()),worsened=int((err>base).sum()))\n quality[view]=q\nprint('SOURCE_GATED_LOW_SNR '+json.dumps(dict(status='SOURCE_ONLY_FRESH_GATED_LOW_SNR',source_ids=n,validation_ids=int((split==1).sum()),heldout_ids=int((split==2).sum()),gate_db=payload['gate_db'],alpha=payload['alpha'],validation=evaluate(1),validation_groups={str(g):evaluate(1,g) for g in (4,6)},heldout=evaluate(2),quality=quality,U_s_labels_read=0,V_reads=0,test_IQ_reads=0,predictions_before_source_tx_labels=True,clean_target_used_for_inference=False,simulated_snr_used_for_inference=False,\n caveat='This fixed model and gate were chosen after earlier source results. Fresh IDs exclude the complete 4096-record cycle-network sample and 8192-record SNR/proxy sample, but may overlap other source diagnostics. New channel and hardware seeds are used. Only source simulator uses source clean IQ and simulator SNR; inference uses received IQ, DURA and the fixed network, with blind SNR computed from received/DURA. Receiver/day holdout is disjoint for this network, not for frozen experts. Simulated satellite is not a validated real link.'),ensure_ascii=False),flush=True)\n"
